-- Backfill the compliance items that 7c468c1a added to already-shipped migrations.
--
-- Commit 7c468c1a (2026-03-19) edited two migrations after they had shipped:
--   20260312100002_compliance_seed.sql          added annual-fund-audit, fatca-crs, insurance-eo,
--                                               insurance-do and insurance-cyber
--   20260312100004_compliance_vehicle_scope.sql  set scope = 'vehicle' on annual-fund-audit and
--                                               fatca-crs
-- The Supabase CLI tracks applied migrations by version, not content, so any database migrated
-- before that commit (production included) never received those rows. Fresh installs get them from
-- the two files, so this is a no-op there: `on conflict (id) do nothing` leaves existing rows alone.
-- Values are copied from the seed (regulation_url '' rather than null, see #54), with the scope
-- 20260312100004 gives each row on a fresh install. See #51 and #55.
insert into compliance_items (id, category, name, short_name, description, frequency, deadline_description, deadline_month, deadline_day, rolling_days, applicability_text, applicability_question, filing_system, filing_portal_url, regulation_url, form_instructions_url, complexity, notes, alert, sort_order, scope) values
('annual-fund-audit', 'Fund Reporting', 'Annual Fund Audit', 'Fund Audit', 'Annual audit of fund financial statements by an independent accounting firm, as typically required by the LPA. Includes coordinating with the auditor, providing supporting schedules, reviewing draft financials, and delivering the final audited statements to LPs.', 'Annual', 'Year-end audit fieldwork typically begins in January–February; audited financials due per LPA (commonly 90–120 days after fiscal year-end)', null, null, null, 'All VC funds with audited financial statement requirements in their LPA.', 'Does your LPA require annual audited financial statements?', 'Internal', null, 'https://www.aicpa.org/resources/article/audit-and-accounting-guide-investment-companies', null, 'high', 'Start auditor engagement and PBC (prepared by client) list well before year-end. Common deliverables: audited financial statements, schedule of investments, partner capital account statements. Year-end valuations are typically part of the audit scope. If using a new auditor, allow extra time for transition.', null, 22, 'vehicle'),
('fatca-crs', 'Tax Filings', 'FATCA / CRS Reporting', 'FATCA/CRS', 'Foreign Account Tax Compliance Act (FATCA) and Common Reporting Standard (CRS) reporting obligations for funds with foreign investors or foreign financial accounts. Includes collecting W-8BEN/W-8BEN-E forms from foreign investors, withholding on payments to foreign persons, and reporting to the IRS (FATCA) or local tax authorities (CRS).', 'Annual', 'FATCA: March 15 (Form 1042-S to recipients), March 15 (Form 1042 to IRS); W-8 forms should be collected at onboarding and renewed every 3 years', 3, 15, null, 'Funds with one or more foreign investors (non-U.S. persons or entities) or foreign financial accounts.', 'Does your fund have any foreign (non-U.S.) investors or foreign financial accounts?', 'IRS e-file', null, 'https://www.irs.gov/businesses/corporations/foreign-account-tax-compliance-act-fatca', null, 'medium', 'Collect W-8BEN or W-8BEN-E from all foreign investors at onboarding — forms expire every 3 years and must be renewed. Withhold 30% on FDAP income to foreign persons unless a treaty rate applies. File Form 1042-S (recipient copy by March 15) and Form 1042 (annual return, March 15). If the fund itself has foreign financial accounts over $10K in aggregate, FBAR (FinCEN 114) is due April 15. For CRS, reporting depends on the jurisdictions where the fund or its administrator operates.', null, 23, 'vehicle'),
('insurance-eo', 'Internal Compliance', 'Errors & Omissions (E&O) Insurance Renewal', 'E&O Insurance', 'Annual renewal of Errors & Omissions / Professional Liability insurance policy. E&O insurance protects the fund manager and its employees against claims of negligent acts, errors, or omissions in the performance of professional duties.', 'Annual', 'Varies by policy — set renewal date when policy is bound', null, null, null, 'All fund managers providing investment advisory services.', 'Does your firm carry Errors & Omissions or Professional Liability insurance?', 'Internal', null, '', null, 'low', 'Start renewal process 60–90 days before expiration. Review coverage limits, deductibles, and any exclusions. Confirm that the policy covers all fund entities and key persons. Some LPAs require minimum E&O coverage — check your LPA terms. Keep certificates of insurance on file for LP requests.', null, 24, 'firm'),
('insurance-do', 'Internal Compliance', 'Directors & Officers (D&O) Insurance Renewal', 'D&O Insurance', 'Annual renewal of Directors & Officers liability insurance policy. D&O insurance protects the personal assets of directors and officers of the management company and its portfolio companies (if covered) against claims alleging wrongful acts in their capacity as directors or officers.', 'Annual', 'Varies by policy — set renewal date when policy is bound', null, null, null, 'Fund managers with a management company board or GP entity with officers/directors.', 'Does your firm carry Directors & Officers liability insurance?', 'Internal', null, '', null, 'low', 'Review whether the policy covers the GP entity, management company, and fund-level directors/officers. Some LPAs require D&O coverage. Side A/B/C coverage distinctions matter — Side A (individual protection when entity cannot indemnify) is most critical. Start renewal 60–90 days before expiration.', null, 25, 'firm'),
('insurance-cyber', 'Internal Compliance', 'Cyber Liability Insurance Renewal', 'Cyber Insurance', 'Annual renewal of Cyber Liability insurance policy. Covers costs associated with data breaches, ransomware, business interruption from cyber events, and regulatory fines related to data privacy incidents.', 'Annual', 'Varies by policy — set renewal date when policy is bound', null, null, null, 'Fund managers handling sensitive investor PII, financial data, or using cloud-based systems.', 'Does your firm carry Cyber Liability insurance?', 'Internal', null, '', null, 'low', 'Increasingly expected by institutional LPs during due diligence. Review coverage for: data breach notification costs, regulatory defense, business interruption, social engineering / wire fraud, and third-party vendor incidents. SEC has signaled cyber risk management is an exam priority. Amended Reg S-P (effective June 3, 2026 for smaller RIAs) requires incident response procedures — cyber insurance should complement your incident response plan.', null, 26, 'firm')
on conflict (id) do nothing;
